      type(zzdnpt_state), allocatable :: zzdnpt_state  !! state of [[zzdnpt]]
      ! --- end pepper_rotations
      ! --- pepper_records
      type(ckr03_state), allocatable :: ckr03_state  !! state of [[ckr03]]
      type(ckr05_state), allocatable :: ckr05_state  !! state of [[ckr05]]
