      module subroutine scs2e ( ctx, sc, sclkch, et )
         implicit none
         class(pepper_context), intent(inout) :: ctx  !! the context
         integer(ip), intent(in) :: sc  !! NAIF integer code for a spacecraft.
         character(*), intent(in) :: sclkch  !! An SCLK string.
