      module subroutine ckobj ( ctx, ckfnm, ids )
         implicit none
         class(pepper_context), intent(inout) :: ctx  !! the context
         integer(ip), parameter :: lbcell = -5
         character(*), intent(in) :: ckfnm  !! Name of CK file.
