         real(wp), intent(in) :: ets(:)  !! the epochs (TDB seconds past J2000)
         real(wp), intent(out) :: states(:,:)  !! the states, shape (6, size(ets)) at least
         real(wp), intent(out), optional :: lts(:)  !! the light times
      end subroutine query_state_batch

