      module subroutine syfetd ( ctx, nth, tabsym, tabptr, tabval, name, found )
         implicit none
         class(pepper_context), intent(inout) :: ctx  !! the context
         integer(ip), parameter :: lbcell = -5
         integer(ip), intent(in) :: nth  !! Index of symbol to be fetched.
