   !> The instance this context belongs to.
   function instance(this) result(spice)
      class(pepper_context), intent(in) :: this  !! the context
      type(pepper_instance), pointer :: spice
      spice => this%spice
   end function instance

   !> True if an error has been signaled and not reset.
   logical function ctx_failed(this)
      class(pepper_context), intent(in) :: this  !! the context
      ctx_failed = this%failure
   end function ctx_failed

   !> True if the routine calling it should return at once: an error was
   !> signaled and the error action is RETURN (SPICELIB's RETURN).
   logical function ctx_return(this)
      class(pepper_context), intent(in) :: this  !! the context
      ctx_return = this%failure .and. this%action == action_return
   end function ctx_return

   !> Signal an error with the short message msg (e.g. 'SPICE(BADINPUT)'),
   !> as SPICELIB's SIGERR: unless the action is IGNORE, the error status is
   !> set and a report is written to the device (the parts selected with
   !> errprt); under RETURN only the first error is kept (further errors and
   !> message changes are ignored until reset()); ABORT and DEFAULT end the
   !> program.
   subroutine ctx_sigerr(this, msg)
      class(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: msg  !! short error message, e.g. 'SPICE(BADINPUT)'
      if (this%action /= action_ignore) then
         if (this%action /= action_return .or. .not. this%failure) then
            this%failure = .true.
            this%short = trim(msg)
            if (this%action /= action_default) then
               call this%outmsg('SHORT, EXPLAIN, LONG, TRACEBACK')
            else
               call this%outmsg('SHORT, EXPLAIN, LONG, TRACEBACK, DEFAULT')
            end if
            this%messages_allowed = this%action /= action_return
         else
            this%messages_allowed = .false.
         end if
      end if
      if (this%action == action_default .or. this%action == action_abort) call byebye('FAILURE')
   end subroutine ctx_sigerr

   !> Set the long error message (before calling sigerr). Markers in it
   !> (e.g. '#') are replaced by errch, errdp, errint, errfnm and errhan.
   subroutine ctx_setmsg(this, msg)
      class(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: msg  !! long error message, with markers to replace
      if (this%messages_allowed) this%long = trim(msg)
   end subroutine ctx_setmsg

   !> Replace the first occurrence of marker in the long message with the
   !> string (without its leading and trailing blanks; a blank string becomes
   !> one blank).
   subroutine ctx_errch(this, marker, string)
      class(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: marker  !! marker in the long message, e.g. '#'
      character(*), intent(in) :: string  !! text that replaces the marker
      if (string == ' ') then
         call replace_marker(this, marker, ' ')
      else
         call replace_marker(this, marker, trim(adjustl(string)))
      end if
   end subroutine ctx_errch

   !> Replace the first occurrence of marker in the long message with the
   !> number, with 14 significant digits (as [[dpstr]] writes it).
   subroutine ctx_errdp(this, marker, number)
      class(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: marker  !! marker in the long message, e.g. '#'
      real(wp), intent(in) :: number  !! number that replaces the marker
      character(32) :: text
      call dpstr(number, 14, text)
      call replace_marker(this, marker, trim(adjustl(text)))
   end subroutine ctx_errdp

   !> Replace the first occurrence of marker in the long message with the
   !> integer.
   subroutine ctx_errint(this, marker, number)
      class(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: marker  !! marker in the long message, e.g. '#'
      integer(ip), intent(in) :: number  !! integer that replaces the marker
      character(16) :: text
      call intstr(number, text)
      call replace_marker(this, marker, trim(adjustl(text)))
   end subroutine ctx_errint

   !> Replace the first occurrence of marker in the long message with the
   !> name of the file connected to a Fortran unit.
   subroutine ctx_errfnm(this, marker, unit)
      class(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: marker  !! marker in the long message, e.g. '#'
      integer(ip), intent(in) :: unit  !! Fortran unit
      character(1024) :: name
      integer :: ios
      name = ' '
      inquire (unit=unit, name=name, iostat=ios)
      if (ios /= 0 .or. name == ' ') name = '<unavailable from the system>'
      call this%errch(marker, name)
   end subroutine ctx_errfnm

   !> The number of values of the body kernel variable BODY<body>_<item>
   !> (0 if there is none): the room the callers of [[bodvcd]] allocate
   !> (PEPPER: SPICELIB used fixed sizes, e.g. [[tisbod]]'s MAXANG).
   function body_item_size(ctx, body, item) result(n)
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: body  !! the body ID code
      character(*), intent(in) :: item  !! the item, e.g. 'NUT_PREC_RA'
      integer(ip) :: n  !! the number of values
      character(80) :: name
      character(1) :: type
      logical :: found
      write (name, '(a,i0,2a)') 'BODY', body, '_', trim(item)
      call ctx%dtpool(name, found, n, type)
      if (.not. found) n = 0
   end function body_item_size

   !> The number of partitions of a spacecraft clock (the size of its
   !> SCLK_PARTITION_START kernel variable), at least 1: the room the
   !> callers of [[scpart]] allocate (PEPPER: SPICELIB used MXPART, 9999).
   function sclk_partition_count(ctx, sc) result(n)
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: sc  !! the spacecraft clock ID
      integer(ip) :: n  !! the number of partitions (at least 1)
      character(40) :: name
      character(1) :: type
      logical :: found
      write (name, '(a,i0)') 'SCLK_PARTITION_START_', -sc
      call ctx%dtpool(name, found, n, type)
      if (.not. found) n = 1
      n = max(1_ip, n)
   end function sclk_partition_count

   !> The length of file_name's result: the length of the file's name, 1
   !> if there is no file with the handle.
   pure integer function file_name_length(spice, handle) result(n)
      type(pepper_instance), intent(in) :: spice  !! the instance
      integer(ip), intent(in) :: handle  !! the handle
      integer(ip) :: i
      n = 1
      i = spice%zzddhman%find(handle)
      if (i > 0) n = len(spice%zzddhman%files(i)%name)
   end function file_name_length

   !> The name of the file with a DAF or DAS handle, whole (blank if no
   !> file has the handle).
   pure function file_name(spice, handle) result(name)
      type(pepper_instance), intent(in) :: spice  !! the instance
      integer(ip), intent(in) :: handle  !! the handle
      character(file_name_length(spice, handle)) :: name  !! the file name
      integer(ip) :: i
      name = ' '
      i = spice%zzddhman%find(handle)
      if (i > 0) name = spice%zzddhman%files(i)%name
   end function file_name

   !> Replace the first occurrence of marker in the long message with the
   !> name of the file with a DAF or DAS handle.
   subroutine ctx_errhan(this, marker, handle)
      class(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: marker  !! marker in the long message, e.g. '#'
      integer(ip), intent(in) :: handle  !! handle of a DAF or DAS file
      character(16) :: number
      integer(ip) :: i
      if (.not. this%messages_allowed) return
      ! the name, whole, from the handle manager's file table
      i = 0
      i = this%spice%zzddhman%find(handle)
      if (i > 0) then
         call this%errch(marker, file_name(this%spice, handle))
      else
         call intstr(handle, number)
         call this%errch(marker, '<No name found for handle ' // trim(number) // '>')
      end if
   end subroutine ctx_errhan

   !> Note that this context wrote a record to a DAF or DAS file: the
   !> instance's file_generation changes, so that other contexts empty their
   !> record caches. This context's caches are consistent with its own
   !> writes, so they stay current if they were.
   subroutine files_written(ctx)
      class(pepper_context), intent(inout) :: ctx  !! the context
      if (ctx%files_seen == ctx%spice%file_generation) ctx%files_seen = ctx%files_seen + 1
      ctx%spice%file_generation = ctx%spice%file_generation + 1
   end subroutine files_written

   !> Before using its DAF/DAS record caches: if another context wrote to a
   !> file since this context filled them, empty them (the DAF record buffer,
   !> the unmodified records of the DAS buffers, and the DAS address cache).
   subroutine files_check(ctx)
      class(pepper_context), intent(inout) :: ctx  !! the context
      if (ctx%files_seen == ctx%spice%file_generation) return
      if (allocated(ctx%dafrwd)) then
         ctx%dafrwd%rbhan = 0
         ctx%dafrwd%rbrec = 0
         ctx%dafrwd%rbreq = 0
      end if
      if (allocated(ctx%dasrwr)) then
         where (.not. ctx%dasrwr%upbufc) ctx%dasrwr%hnbufc = 0
         where (.not. ctx%dasrwr%upbufd) ctx%dasrwr%hnbufd = 0
         where (.not. ctx%dasrwr%upbufi) ctx%dasrwr%hnbufi = 0
      end if
      if (allocated(ctx%dasa2l_state)) then
         ctx%dasa2l_state%tbhan = 0
         ctx%dasa2l_state%nfiles = 0
         ctx%dasa2l_state%prvhan = 0
         ctx%dasa2l_state%fidx = 0
         ctx%dasa2l_state%prvok = .false.
      end if
      ! This context's units are closed too (the handle manager reopens them
      ! when needed), so that no I/O buffer of the runtime library holds old
      ! data: all except locked units and scratch files (which would be
      ! deleted). (A context that wrote is current, so its units stay open.)
      if (allocated(ctx%zzddhman_units)) then
         block
            integer(ip) :: k, f
            integer :: ios
            associate (u => ctx%zzddhman_units, ft => ctx%spice%zzddhman)
               do k = 1, u%nut
                  if (u%uthan(k) == 0 .or. u%utlck(k)) cycle
                  f = ft%find(u%uthan(k))
                  if (f == 0) cycle
                  if (ft%files(f)%method == 3) cycle      ! SCRATCH access
                  close (unit=u%utlun(k), iostat=ios)
                  u%uthan(k) = 0
                  u%utcst(k) = 0
                  u%utlun(k) = -1
               end do
            end associate
         end block
      end if
      ctx%files_seen = ctx%spice%file_generation
   end subroutine files_check

   !> The index in the instance's file table of the DAF `handle` if the file
   !> is in memory, else 0. The context keeps the last lookup until the
   !> table changes (a file opened or closed).
   integer(ip) function daf_image_slot(ctx, handle) result(k)
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! the handle of the DAF
      k = 0
      associate (ft => ctx%spice%zzddhman)
         if (handle /= ctx%img_handle .or. ctx%img_changes /= ft%changes) then
            ctx%img_handle = handle
            ctx%img_slot = ft%find(handle)
            ctx%img_changes = ft%changes
         end if
         k = ctx%img_slot
         if (k > 0) then
            if (.not. allocated(ft%files(k)%image)) k = 0
         end if
      end associate
   end function daf_image_slot

   !> The index in the instance's file table of the DAF `handle` if the file
   !> has raw 1024-byte records in memory ([[spice_furnsh_memory]]), else 0.
   integer(ip) function daf_raw_slot(ctx, handle) result(k)
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! the handle of the DAF
      k = daf_image_slot(ctx, handle)
      if (k > 0) then
         if (.not. allocated(ctx%spice%zzddhman%files(k)%raw_records)) k = 0
      end if
   end function daf_raw_slot

   !> The index in the instance's file table of the DAF `handle` if it was
   !> built in memory (it has no file: [[spice_load_kernel]], or a kernel
   !> loader's), else 0. Its records are read from its image, always.
   integer(ip) function daf_synthetic_slot(ctx, handle) result(k)
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! the handle of the DAF
      k = daf_image_slot(ctx, handle)
      if (k > 0) then
         if (.not. ctx%spice%zzddhman%files(k)%synthetic) k = 0
      end if
   end function daf_synthetic_slot

   !> The index in the instance's file table of the DAF built in memory
   !> named `name` (the most recently loaded, if several), else 0 (always
   !> 0 while `zzddhman%files_only` is set: ZZLDKER loading from disk).
   integer(ip) function synthetic_named(ctx, name) result(k)
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: name  !! the kernel's name
      k = 0
      if (ctx%spice%zzddhman%files_only) return   ! ZZLDKER reads a file from disk
      associate (ft => ctx%spice%zzddhman)
         do k = ft%nft, 1, -1
            if (.not. ft%files(k)%synthetic) cycle
            if (ft%files(k)%name == trim(adjustl(name))) return
         end do
      end associate
      k = 0
   end function synthetic_named

   !> Record `recno` of a DAF image as characters: the bytes of its 128
   !> double precision words (the image of a native file).
   pure function daf_image_chars(image, recno) result(rec)
      real(wp), intent(in) :: image(:)  !! the DAF image (whole records)
      integer(ip), intent(in) :: recno  !! the record number
      character(1024) :: rec  !! the record's 1024 bytes
      rec = transfer(image(128*(recno - 1) + 1:128*recno), rec)
   end function daf_image_chars

   !> The items of the file record (record 1) of a native DAF image, as
   !> ZZDAFGFR reads them from a native file: ID word, ND, NI, internal
   !> file name, forward and backward pointers, free address.
   pure subroutine daf_image_file_record(image, idword, nd, ni, ifname, fward, bward, free)
      real(wp), intent(in) :: image(:)  !! the DAF image
      character(*), intent(out) :: idword  !! the ID word
      integer(ip), intent(out) :: nd  !! number of double precision components of a summary
      integer(ip), intent(out) :: ni  !! number of integer components of a summary
      character(*), intent(out) :: ifname  !! the internal file name
      integer(ip), intent(out) :: fward  !! the first summary record
      integer(ip), intent(out) :: bward  !! the last summary record
      integer(ip), intent(out) :: free  !! the first free address
      character(1024) :: rec
      rec = daf_image_chars(image, 1_ip)
      idword = rec(1:8)
      nd = transfer(rec(9:12), nd)
      ni = transfer(rec(13:16), ni)
      ifname = rec(17:76)
      fward = transfer(rec(77:80), fward)
      bward = transfer(rec(81:84), bward)
      free = transfer(rec(85:88), free)
   end subroutine daf_image_file_record

   !> Read the DAF `handle` whole into memory (FURNSH's `in_memory`; the
   !> instance's context, while no queries run). A file in a non-native
   !> binary format is translated, so the copy is always native. Nothing
   !> happens if the file is in memory already. Signals SPICE(MALLOCFAILED)
   !> if the memory cannot be allocated, and SPICE(FILEREADFAILED) if the file
   !> cannot be read.
   !>
   !> The records are read as SPICELIB's DAF readers read them (ZZDAFGDR):
   !> through the handle manager's unit for the file (direct access, records
   !> of 1024 bytes), one record at a time, without a second connection to
   !> the file.
   subroutine daf_load_image(ctx, handle)
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! the handle of the DAF (loaded for reading)
      integer, parameter :: recl = 1024  !! bytes per DAF record
      integer(ip) :: k, r, lun
      integer :: ios, stat
      integer(int64) :: nbytes, nrec
      logical :: native, found
      real(wp), allocatable :: image(:)
      character(recl) :: chrbuf
      if (ctx%failed()) return
      k = ctx%spice%zzddhman%find(handle)
      if (k == 0) return
      if (allocated(ctx%spice%zzddhman%files(k)%image)) return
      call zzddhisn(ctx, handle, native, found)
      if (ctx%failed() .or. .not. found) return
      ! the handle manager's unit for the file (opened if needed)
      call zzddhhlu(ctx, handle, 'DAF', .false., lun)
      if (ctx%failed()) return
      k = ctx%spice%zzddhman%find(handle)
      associate (f => ctx%spice%zzddhman%files(k))
         inquire (file=f%name, size=nbytes)
         if (nbytes < 0) then
            call ctx%setmsg('The size of the file ''#'' is not known: it cannot be read into memory.')
            call ctx%errch('#', f%name)
            call ctx%sigerr('SPICE(FILEREADFAILED)')
            return
         end if
         nrec = nbytes/recl
         allocate (image(128*nrec), stat=stat)
         if (stat /= 0) then
            call ctx%setmsg('Not enough memory to read the file ''#'' (# bytes) into memory.')
            call ctx%errch('#', f%name)
            call ctx%errint('#', int(min(nbytes, int(huge(1_ip), int64)), ip))
            call ctx%sigerr('SPICE(MALLOCFAILED)')
            return
         end if
         ios = 0
         do r = 1, int(nrec, ip)
            if (native) then
               read (lun, rec=r, iostat=ios) image(128*(r - 1) + 1:128*r)
            else
               read (lun, rec=r, iostat=ios) chrbuf
               if (ios == 0) call zzxlated(ctx, f%bff, chrbuf, 128_ip, image(128*(r - 1) + 1:128*r))
            end if
            if (ios /= 0 .or. ctx%failed()) exit
         end do
         if (ctx%failed()) return
         if (ios /= 0) then
            call ctx%setmsg('The file ''#'' could not be read into memory (record #, IOSTAT #).')
            call ctx%errch('#', f%name)
            call ctx%errint('#', r)
            call ctx%errint('#', int(ios, ip))
            call ctx%sigerr('SPICE(FILEREADFAILED)')
            return
         end if
         call move_alloc(image, f%image)
      end associate
   end subroutine daf_load_image

   !> Note that a file was closed: other contexts close their units for its
   !> handle when they next use their unit tables, and a later open of the
   !> file is not refused because such a unit is still connected to it.
   subroutine file_closed(spice, name)
      type(pepper_instance), intent(inout) :: spice  !! the instance
      character(*), intent(in) :: name  !! name of the file
      call spice%closed_files%set(name, 1_ip)
      spice%close_generation = spice%close_generation + 1
   end subroutine file_closed

   !> Record a change of a kernel pool variable (name blank: of every
   !> variable, e.g. by CLPOOL), for the watches of the contexts.
   subroutine pool_changed(spice, name)
      type(pepper_instance), intent(inout) :: spice  !! the instance
      character(*), intent(in) :: name  !! the variable changed, or blank
      spice%pool_changes = spice%pool_changes + 1
      if (name == ' ' .or. spice%nchanged == change_log_size) then
         spice%all_changed_at = spice%pool_changes
         spice%nchanged = 0
         if (name == ' ') return
      end if
      if (.not. allocated(spice%changed_names)) then
         allocate (spice%changed_names(change_log_size), spice%changed_at(change_log_size))
      end if
      spice%nchanged = spice%nchanged + 1
      spice%changed_names(spice%nchanged)%s = trim(name)
      spice%changed_at(spice%nchanged) = spice%pool_changes
   end subroutine pool_changed

   !> The index of an agent in the context's watch table (0: none).
   integer function watch_index(ctx, agent)
      class(pepper_context), intent(in) :: ctx  !! the context
      character(*), intent(in) :: agent  !! the agent
      integer(ip) :: k
      logical :: found
      call ctx%watch_map%get(agent, k, found)
      watch_index = k
   end function watch_index

   !> [[swpool]] for a context: the watch is the
   !> context's own, so that contexts do not take each other's notices, and
   !> setting it changes nothing that other contexts use. As with [[swpool]], the
   !> agent's variables are added to those it watches already, and a notice
   !> is posted for it.
   subroutine swpool_context(ctx, agent, nnames, names)
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: agent  !! the agent to notify of updates
      integer(ip), intent(in) :: nnames  !! number of variables
      character(*), intent(in) :: names(*)  !! the variables to watch
      type(pool_watch), allocatable :: grown(:)
      type(string), allocatable :: more(:)
      integer :: k, i, j
      k = watch_index(ctx, agent)
      if (k == 0) then
         if (.not. allocated(ctx%watches)) allocate (ctx%watches(8))
         if (ctx%nwatches == size(ctx%watches)) then
            allocate (grown(2*ctx%nwatches))
            grown(1:ctx%nwatches) = ctx%watches
            call move_alloc(grown, ctx%watches)
         end if
         ctx%nwatches = ctx%nwatches + 1
         k = ctx%nwatches
         ctx%watches(k)%agent = trim(agent)
         call ctx%watch_map%set(agent, int(k, ip))
         ctx%watches(k)%nnames = 0
         allocate (ctx%watches(k)%names(max(8, int(nnames))))
      end if
      associate (w => ctx%watches(k))
         do i = 1, nnames
            if (watches(w, names(i))) cycle
            if (w%nnames == size(w%names)) then
               allocate (more(2*w%nnames))
               do j = 1, w%nnames
                  call move_alloc(w%names(j)%s, more(j)%s)
               end do
               call move_alloc(more, w%names)
            end if
            w%nnames = w%nnames + 1
            w%names(w%nnames)%s = trim(names(i))
         end do
         w%seen = -1
      end associate
   end subroutine swpool_context

   !> True if a watch is on a variable.
   pure logical function watches(w, name)
      type(pool_watch), intent(in) :: w  !! the watch
      character(*), intent(in) :: name  !! the variable
      integer :: i
      watches = .false.
      do i = 1, w%nnames
         if (w%names(i)%s == name) then
            watches = .true.
            return
         end if
      end do
   end function watches

   !> True if a variable watched by the context's watch k changed since the
   !> watch's last check (or a notice is pending).
   logical function watch_pending(ctx, k)
      class(pepper_context), intent(in) :: ctx  !! the context
      integer, intent(in) :: k  !! index of the watch
      integer :: j
      associate (w => ctx%watches(k), s => ctx%spice)
         watch_pending = w%seen < 0 .or. s%all_changed_at > w%seen
         if (watch_pending .or. s%pool_changes == w%seen) return
         ! the log is in the order of the changes: look at the newer ones
         do j = s%nchanged, 1, -1
            if (s%changed_at(j) <= w%seen) exit
            if (watches(w, s%changed_names(j)%s)) then
               watch_pending = .true.
               return
            end if
         end do
      end associate
   end function watch_pending

   !> [[cvpool]] for a context: true if a variable the
   !> agent watches (in this context) was updated since the last check.
   subroutine cvpool_context(ctx, agent, update)
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: agent  !! the agent
      logical, intent(out) :: update  !! a watched variable was updated
      integer :: k
      update = .false.
      k = watch_index(ctx, agent)
      if (k == 0) return
      update = watch_pending(ctx, k)
      ctx%watches(k)%seen = ctx%spice%pool_changes
   end subroutine cvpool_context

   !> [[dwpool]] for a context: delete the agent's
   !> watch; SPICE(UPDATEPENDING) if it has an unchecked update.
   subroutine dwpool_context(ctx, agent)
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: agent  !! the agent
      integer :: k
      k = watch_index(ctx, agent)
      if (k == 0) return
      if (watch_pending(ctx, k)) then
         call ctx%setmsg('Could not delete AGENT # from the watch symbol table because AGENT '// &
                         'is associated with at least one updated kernel variable. ')
         call ctx%errch('#', agent)
         call ctx%sigerr('SPICE(UPDATEPENDING)')
         return
      end if
      ! The last watch takes the place of the deleted one (the order of the
      ! watches does not matter: an agent has one watch); its components
      ! are moved, not copied.
      call ctx%watch_map%remove(agent)
      associate (w => ctx%watches(k), last => ctx%watches(ctx%nwatches))
         if (k /= ctx%nwatches) then
            call ctx%watch_map%set(last%agent, int(k, ip))
            call move_alloc(last%agent, w%agent)
            call move_alloc(last%names, w%names)
            w%nnames = last%nnames
            w%seen = last%seen
         end if
         if (allocated(last%agent)) deallocate (last%agent)
         if (allocated(last%names)) deallocate (last%names)
         last%nnames = 0
      end associate
      ctx%nwatches = ctx%nwatches - 1
   end subroutine dwpool_context

   !> True if a file of this name was closed through this instance before.
   logical function was_closed(spice, name)
      type(pepper_instance), intent(in) :: spice  !! the instance
      character(*), intent(in) :: name  !! name of the file
      integer(ip) :: value
      call spice%closed_files%get(name, value, was_closed)
   end function was_closed

   !> True if a file connected to a unit was opened by PEPPER, so that
   !> reading it through a unit of its own is safe: it was closed through
   !> this instance (a context still has a unit on it, closed when the
   !> context next uses its unit table), or its unit is one NEWUNIT= gave
   !> (negative), as all of PEPPER's are: another instance's, or another
   !> context's. SPICELIB refused to load a file connected to a unit it did
   !> not know (SPICE(EXTERNALOPEN), SPICE(FILEOPENCONFLICT)); with several
   !> instances and contexts, one process opens a kernel on several units.
   logical function opened_by_pepper(spice, name)
      type(pepper_instance), intent(in) :: spice  !! the instance
      character(*), intent(in) :: name  !! name of the file
      integer :: unit, ios
      opened_by_pepper = was_closed(spice, name)
      if (opened_by_pepper) return
      inquire (file=name, number=unit, iostat=ios)
      opened_by_pepper = ios == 0 .and. unit < 0 .and. unit /= -1
   end function opened_by_pepper

   !> If files were closed (through any context) since this context last
   !> looked, close this context's units for the handles that are not in the
   !> file table any more, and mark their rows of the unit table free. Only
   !> the context that opened a unit closes it, so a unit number that NEWUNIT=
   !> gave to another file is never closed by mistake.
   subroutine units_check(ctx)
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip) :: k
      integer :: ios
      if (.not. allocated(ctx%zzddhman_units)) return
      if (ctx%zzddhman_units%closegen == ctx%spice%close_generation) return
      associate (u => ctx%zzddhman_units)
         do k = 1, u%nut
            if (u%uthan(k) == 0) cycle
            if (ctx%spice%zzddhman%find(u%uthan(k)) > 0) cycle
            close (unit=u%utlun(k), iostat=ios)
            u%uthan(k) = 0
            u%utcst(k) = 0
            u%utlck(k) = .false.
            u%utlun(k) = -1
         end do
         u%closegen = ctx%spice%close_generation
      end associate
   end subroutine units_check

   !> Finalization of a context: close the units it opened (each context
   !> opens its own units for the instance's files; see units_check). A
   !> context must not be copied while it has open units: the copy's
   !> finalization would close them too. Elemental, so that the elements of
   !> an array of contexts are finalized too (a final subroutine for a
   !> scalar is not called for them).
   impure elemental subroutine ctx_final(this)
      type(pepper_context), intent(inout) :: this  !! the context
      integer(ip) :: k
      integer :: ios
      logical :: opened
      if (.not. allocated(this%zzddhman_units)) return
      associate (u => this%zzddhman_units)
         do k = 1, u%nut
            ! (units from NEWUNIT= are negative; -1 marks a free entry)
            if (u%utlun(k) /= -1 .and. u%utlun(k) /= 0) then
               inquire (unit=u%utlun(k), opened=opened, iostat=ios)
               if (ios == 0 .and. opened) close (unit=u%utlun(k), iostat=ios)
            end if
            u%utlun(k) = -1
            u%uthan(k) = 0
         end do
         u%nut = 0
      end associate
   end subroutine ctx_final

   !> Destroy the context: close the file units it opened and release all
   !> its memory (its caches, its error messages and settings, its
   !> watches). It is then detached from its instance; make it again with
   !> spice%new_context() to use it.
   !>
   !> PEPPER: no SPICELIB counterpart. A context is also destroyed when it
   !> goes out of scope or is deallocated, but not one declared in a main
   !> program (or a module), which lives until the program ends.
   subroutine ctx_destroy(this)
      class(pepper_context), intent(inout) :: this  !! the context
      call ctx_final(this)
      call reset_context(this)
   contains
      !> The context's default values (its allocatable components deallocated).
      subroutine reset_context(ctx)
         type(pepper_context), intent(out) :: ctx  !! the context
      end subroutine reset_context
   end subroutine ctx_destroy

   !> Close the context's units for the files that are no longer loaded
   !> (unloaded, or closed, through any context of the instance).
   !>
   !> PEPPER: no SPICELIB counterpart. Each context opens its own units for
   !> the files it reads, and closes those of unloaded files on its next
   !> access to a file (the instance cannot reach the program's contexts).
   !> On Windows, where an open file cannot be deleted or replaced, call this
   !> in every context that read a file (or destroy them) before deleting
   !> it after the instance unloaded it.
   subroutine ctx_close_unloaded_files(this)
      class(pepper_context), intent(inout) :: this  !! the context
      call units_check(this)
   end subroutine ctx_close_unloaded_files

   !> Clear the error status and the messages.
   subroutine ctx_reset(this)
      class(pepper_context), intent(inout) :: this  !! the context
      this%failure = .false.
      this%short = ''
      this%long = ''
      this%messages_allowed = .true.
   end subroutine ctx_reset

   !> Get an error message: option 'SHORT', 'LONG' or 'EXPLAIN' (the
   !> explanation of the short message), case-insensitive. A message longer
   !> than `msg` is cut to its length; `message` returns it whole.
   subroutine ctx_getmsg(this, option, msg)
      class(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: option  !! 'SHORT', 'LONG' or 'EXPLAIN'
      character(*), intent(out) :: msg  !! the message
      select case (upper(adjustl(option)))
      case ('SHORT')
         msg = short_text(this)
      case ('EXPLAIN')
         call expln(short_text(this), msg)
      case ('LONG')
         msg = long_text(this)
      case default
         call this%setmsg('GETMSG: An invalid value of OPTION was input.  Valid choices are ''SHORT'','// &
                          '       ''EXPLAIN'', or ''LONG''.  The value that was input was:  ' // option)
         call this%sigerr('SPICE(INVALIDMSGTYPE)')
      end select
   end subroutine ctx_getmsg

   !> The length of [[ctx_message]]'s result for an option.
   pure integer function message_length(this, option) result(n)
      class(pepper_context), intent(in) :: this  !! the context
      character(*), intent(in) :: option  !! 'SHORT', 'LONG' or 'EXPLAIN'
      character(explanation_length) :: xmsg
      select case (upper(adjustl(option)))
      case ('SHORT')
         n = text_length(this%short)
      case ('EXPLAIN')
         call expln(short_text(this), xmsg)
         n = len_trim(xmsg)
      case ('LONG')
         n = text_length(this%long)
      case default
         n = 0
      end select
   end function message_length

   !> An error message, whole: option 'SHORT', 'LONG' or 'EXPLAIN' (as
   !> getmsg), case-insensitive. Blank if there is no error; an invalid
   !> option signals SPICE(INVALIDMSGTYPE) and returns a blank.
   function ctx_message(this, option) result(msg)
      class(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: option  !! 'SHORT', 'LONG' or 'EXPLAIN'
      character(message_length(this, option)) :: msg  !! the message (without trailing blanks)
      character(explanation_length) :: xmsg
      select case (upper(adjustl(option)))
      case ('SHORT')
         msg = short_text(this)
      case ('EXPLAIN')
         call expln(short_text(this), xmsg)
         msg = trim(xmsg)
      case ('LONG')
         msg = long_text(this)
      case default
         msg = ''
         call this%getmsg(option, xmsg)
      end select
   end function ctx_message

   !> Get (op = 'GET') or set (op = 'SET') the error action: 'ABORT',
   !> 'REPORT', 'RETURN', 'IGNORE' or 'DEFAULT'.
   subroutine ctx_erract(this, op, action)
      class(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: op  !! 'GET' or 'SET'
      character(*), intent(inout) :: action  !! the action (output for 'GET', input for 'SET')
      integer :: k
      select case (upper(adjustl(op)))
      case ('GET')
         action = action_names(this%action)
      case ('SET')
         k = findloc(action_names, upper(adjustl(action)), dim=1)
         if (k > 0) then
            this%action = k
         else
            call this%setmsg('ERRACT: An invalid value of ACTION was supplied.  The value was:  ' // action)
            call this%sigerr('SPICE(INVALIDACTION)')
         end if
      case default
         call this%setmsg('ERRACT: An invalid value of OP was supplied.  The value was:  ' // op)
         call this%sigerr('SPICE(INVALIDOPERATION)')
      end select
   end subroutine ctx_erract

   !> Get (op = 'GET') or set (op = 'SET') the device the error reports are
   !> written to: 'SCREEN', 'NULL' or the name of a file (of any length:
   !> SPICELIB's limit of 255 characters and its DEVICENAMETOOLONG error
   !> are gone).
   subroutine ctx_errdev(this, op, device)
      class(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: op  !! 'GET' or 'SET'
      character(*), intent(inout) :: device  !! the device (output for 'GET', input for 'SET')
      character(len(device)) :: up
      select case (upper(adjustl(op)))
      case ('GET')
         device = device_text(this)
      case ('SET')
         up = upper(adjustl(device))
         if (up == 'SCREEN' .or. up == 'NULL') then
            this%device = trim(up)
         else
            this%device = trim(device)
         end if
      case default
         call this%setmsg('ERRDEV:  An invalid value of OP was supplied.  The value was: ' // op)
         call this%sigerr('SPICE(INVALIDOPERATION)')
      end select
   end subroutine ctx_errdev

   !> Get (op = 'GET') or change (op = 'SET') the parts of an error report
   !> that are written: a list of SHORT, LONG, EXPLAIN, TRACEBACK, DEFAULT,
   !> ALL (the first four) and NONE, separated by commas. 'SET' adds the
   !> parts named (NONE removes all of them first).
   subroutine ctx_errprt(this, op, list)
      class(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: op  !! 'GET' or 'SET'
      character(*), intent(inout) :: list  !! the list (output for 'GET', input for 'SET')
      character(16) :: words(10)
      integer(ip) :: nwords, i
      logical :: s, l, x, tr, d
      s = this%print_short; l = this%print_long; x = this%print_explain
      tr = this%print_trace; d = this%print_default
      select case (upper(adjustl(op)))
      case ('GET')
         list = ' '
         if (s) call add('SHORT')
         if (l) call add('LONG')
         if (x) call add('EXPLAIN')
         if (tr) call add('TRACEBACK')
         if (d) call add('DEFAULT')
      case ('SET')
         call lparse(list, ',', size(words, kind=ip), nwords, words)
         do i = 1, nwords
            select case (upper(words(i)))
            case ('SHORT')
               s = .true.
            case ('LONG')
               l = .true.
            case ('EXPLAIN')
               x = .true.
            case ('TRACEBACK')
               tr = .true.
            case ('ALL')
               s = .true.; l = .true.; x = .true.; tr = .true.
            case ('DEFAULT')
               s = .true.; l = .true.; x = .true.; tr = .true.; d = .true.
            case ('NONE')
               s = .false.; l = .false.; x = .false.; tr = .false.; d = .false.
            case (' ')
            case default
               call this%setmsg('ERRPRT: An invalid list item was found in the error message list.  '// &
                                'The word was:' // words(i))
               call this%sigerr('SPICE(INVALIDLISTITEM)')
            end select
         end do
         if (this%setprt(s, x, l, tr, d)) continue
      case default
         call this%setmsg('ERRPRT:  An invalid value of OP was supplied.  The value was: ' // op)
         call this%sigerr('SPICE(INVALIDOPERATION)')
      end select
   contains
      subroutine add(word)
         character(*), intent(in) :: word
         if (list == ' ') then
            list = word
         else
            list = trim(list) // ', ' // word
         end if
      end subroutine add
   end subroutine ctx_errprt

   !> Write an error report with the parts in list (SHORT, EXPLAIN, LONG,
   !> TRACEBACK, DEFAULT) that are also selected with errprt, to the device
   !> (SPICELIB's OUTMSG; its format).
   subroutine ctx_outmsg(this, list)
      class(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: list  !! the parts of the report to write
      integer, parameter :: ll = 80  !! length of an output line
      character(ll), parameter :: defmsg(4) = [character(ll) :: &
         'Oh, by the way:  The SPICELIB error handling actions are USER-TAILORABLE.  You', &
         'can choose whether the Toolkit aborts or continues when errors occur, which', &
         'error messages to output, and where to send the output.  Please read the ERROR', &
         '"Required Reading" file, or see the routines ERRACT, ERRDEV, and ERRPRT.']
      character(16) :: words(5)
      character(ll) :: border
      character(explanation_length) :: xmsg
      character(:), allocatable :: dev, sms, lms
      character(80) :: versn
      integer(ip) :: nwords, i
      integer :: k, e
      logical :: short, expl, long, dfault
      dev = device_text(this)
      border = repeat('=', ll)
      short = .false.; expl = .false.; long = .false.; dfault = .false.
      call lparse(list, ',', size(words, kind=ip), nwords, words)
      do i = 1, nwords
         select case (upper(words(i)))
         case ('SHORT')
            short = .true.
         case ('EXPLAIN')
            expl = .true.
         case ('LONG')
            long = .true.
         case ('TRACEBACK')
         case ('DEFAULT')
            dfault = .true.
         case default
            call wrline(dev, 'SPICE(INVALIDLISTITEM)')
            call wrline(dev, ' ')
            call wrline(dev, 'OUTMSG:  An invalid message type was specified in the type list. ')
            call wrline(dev, 'The invalid message type was ' // words(i))
         end select
      end do
      short = short .and. this%print_short
      expl = expl .and. this%print_explain
      long = long .and. this%print_long
      dfault = dfault .and. this%print_default
      if (.not. (short .or. expl .or. long .or. dfault) .or. upper(adjustl(dev)) == 'NULL') return
      sms = short_text(this)
      call wrline(dev, ' ')
      call wrline(dev, border)
      call wrline(dev, ' ')
      call tkvrsn(this, 'TOOLKIT', versn)
      call wrline(dev, 'Toolkit version: ' // versn)
      call wrline(dev, ' ')
      if (short .and. expl) then
         call expln(sms, xmsg)
         call wrline(dev, sms // ' -- ' // xmsg)
         call wrline(dev, ' ')
      else if (short) then
         call wrline(dev, sms)
         call wrline(dev, ' ')
      else if (expl) then
         call expln(sms, xmsg)
         call wrline(dev, xmsg)
         call wrline(dev, ' ')
      end if
      if (long) then
         ! the long message in lines of at most LL characters, broken
         ! between words (words longer than a line are split)
         lms = long_text(this)
         block
            character(ll) :: line
            integer :: start, remain
            line = ' '
            start = 1
            k = 1
            do
               ! the next word: lms(k:e)
               do while (k <= len(lms))
                  if (lms(k:k) /= ' ') exit
                  k = k + 1
               end do
               if (k > len(lms)) exit
               e = index(lms(k:), ' ')
               if (e == 0) then
                  e = len(lms)
               else
                  e = k + e - 2
               end if
               if (start + (e - k + 1) <= ll) then
                  line(start:) = lms(k:e)
                  start = start + (e - k + 1) + 1
               else if (e - k + 1 <= ll) then
                  call wrline(dev, line)
                  line = lms(k:e)
                  start = (e - k + 1) + 2
               else
                  ! a word longer than a line: fill the rest of the line
                  ! (or a new one if fewer than 10 places are left), then
                  ! whole lines
                  remain = ll
                  if (start > 1) remain = ll - start
                  if (remain < 10) then
                     call wrline(dev, line)
                     line = ' '
                     remain = ll
                     start = 1
                  end if
                  do while (e - k + 1 > ll)
                     line(start:) = lms(k:k + remain - 1)
                     call wrline(dev, line)
                     k = k + remain
                     line = ' '
                     remain = ll
                     start = 1
                  end do
                  line = lms(k:e)
                  start = (e - k + 1) + 2
               end if
               k = e + 1
            end do
            if (line /= ' ') call wrline(dev, line)
         end block
         call wrline(dev, ' ')
      end if
      if (dfault) then
         do i = 1, size(defmsg)
            call wrline(dev, defmsg(i))
         end do
         call wrline(dev, ' ')
      end if
      call wrline(dev, border)
   end subroutine ctx_outmsg

   ! ------------------------------------------------------------------------
   ! SPICELIB's storage of the error state (SETERR, ACCEPT, ...): public in
   ! SPICELIB, used by its error routines; here they act on the context.

   !> Set the error status; returns .true. (SPICELIB's SETERR).
   logical function ctx_seterr(this, status)
      class(pepper_context), intent(inout) :: this  !! the context
      logical, intent(in) :: status  !! the error status
      this%failure = status
      ctx_seterr = .true.
   end function ctx_seterr

   !> Allow (ok = .true.) or forbid changes of the long message; returns
   !> .false. (SPICELIB's ACCEPT).
   logical function ctx_accept(this, ok)
      class(pepper_context), intent(inout) :: this  !! the context
      logical, intent(in) :: ok  !! changes of the long message are allowed
      this%messages_allowed = ok
      ctx_accept = .false.
   end function ctx_accept

   !> True if changes of the long message are allowed (SPICELIB's ALLOWD).
   logical function ctx_allowd(this)
      class(pepper_context), intent(in) :: this  !! the context
      ctx_allowd = this%messages_allowed
   end function ctx_allowd

   !> The short error message (SPICELIB's GETSMS).
   subroutine ctx_getsms(this, msg)
      class(pepper_context), intent(in) :: this  !! the context
      character(*), intent(out) :: msg  !! the short message
      msg = short_text(this)
   end subroutine ctx_getsms

   !> Store the short error message (SPICELIB's PUTSMS).
   subroutine ctx_putsms(this, msg)
      class(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: msg  !! the short message
      this%short = trim(msg)
   end subroutine ctx_putsms

   !> The long error message (SPICELIB's GETLMS).
   subroutine ctx_getlms(this, msg)
      class(pepper_context), intent(in) :: this  !! the context
      character(*), intent(out) :: msg  !! the long message
      msg = long_text(this)
   end subroutine ctx_getlms

   !> Store the long error message (SPICELIB's PUTLMS).
   subroutine ctx_putlms(this, msg)
      class(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: msg  !! the long message
      this%long = trim(msg)
   end subroutine ctx_putlms

   !> The error action as a code: 1 ABORT, 2 REPORT, 3 RETURN, 4 IGNORE,
   !> 5 DEFAULT (SPICELIB's GETACT).
   subroutine ctx_getact(this, action)
      class(pepper_context), intent(in) :: this  !! the context
      integer(ip), intent(out) :: action  !! the action code
      action = this%action
   end subroutine ctx_getact

   !> Store the error action code (SPICELIB's PUTACT; see getact).
   subroutine ctx_putact(this, action)
      class(pepper_context), intent(inout) :: this  !! the context
      integer(ip), intent(in) :: action  !! the action code
      this%action = action
   end subroutine ctx_putact

   !> The device of the error reports (SPICELIB's GETDEV).
   subroutine ctx_getdev(this, device)
      class(pepper_context), intent(in) :: this  !! the context
      character(*), intent(out) :: device  !! the device
      device = device_text(this)
   end subroutine ctx_getdev

   !> Store the device of the error reports (SPICELIB's PUTDEV).
   subroutine ctx_putdev(this, device)
      class(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: device  !! the device
      this%device = trim(device)
   end subroutine ctx_putdev

   !> Select the parts of the error reports; returns .true. (SPICELIB's
   !> SETPRT).
   logical function ctx_setprt(this, short, expl, long, trace, dfault)
      class(pepper_context), intent(inout) :: this  !! the context
      logical, intent(in) :: short  !! the short message
      logical, intent(in) :: expl  !! the explanation of the short message
      logical, intent(in) :: long  !! the long message
      logical, intent(in) :: trace  !! the traceback
      logical, intent(in) :: dfault  !! the note on the default error handling
      this%print_short = short
      this%print_explain = expl
      this%print_long = long
      this%print_trace = trace
      this%print_default = dfault
      ctx_setprt = .true.
   end function ctx_setprt

   !> True if a part of the error reports is selected: SHORT, EXPLAIN, LONG,
   !> TRACEBACK or DEFAULT (SPICELIB's MSGSEL).
   logical function ctx_msgsel(this, type)
      class(pepper_context), intent(in) :: this  !! the context
      character(*), intent(in) :: type  !! the part
      select case (upper(adjustl(type)))
      case ('SHORT')
         ctx_msgsel = this%print_short
      case ('EXPLAIN')
         ctx_msgsel = this%print_explain
      case ('LONG')
         ctx_msgsel = this%print_long
      case ('TRACEBACK')
         ctx_msgsel = this%print_trace
      case ('DEFAULT')
         ctx_msgsel = this%print_default
      case default
         call wrline(device_text(this), 'SPICE(INVALIDMSGTYPE)')
         call wrline(device_text(this), ' ')
         call wrline(device_text(this), 'MSGSEL:  An invalid message type was specified: ' // type)
         ctx_msgsel = .false.
      end select
   end function ctx_msgsel

   ! ------------------------------------------------------------------------
   ! Logical units (SPICELIB's GETLUN, FNDLUN, RESLUN, FRELUN). PEPPER opens
   ! its files with NEWUNIT=; these are for programs that want a unit
   ! number from 1 to 99 to open a file themselves. The reserved units belong
   ! to the instance.

   !> A free logical unit (not open, not reserved), or 0 if there is none,
   !> or -IOSTAT if INQUIRE failed (SPICELIB's FNDLUN).
   subroutine ctx_fndlun(this, unit)
      class(pepper_context), intent(inout) :: this  !! the context
      integer(ip), intent(out) :: unit  !! the unit
      integer :: i, k, ios
      logical :: opened
      associate (s => this%spice)
         do k = 1, 99
            i = modulo(s%last_unit + k - 1, 99) + 1
            if (s%reserved_units(i)) cycle
            inquire (unit=i, opened=opened, iostat=ios)
            if (ios > 0) then
               unit = -ios
               return
            end if
            if (.not. opened) then
               unit = i
               s%last_unit = i
               return
            end if
         end do
      end associate
      unit = 0
   end subroutine ctx_fndlun

   !> A free logical unit; signals SPICE(NOFREELOGICALUNIT) if there is none
   !> (SPICELIB's GETLUN).
   subroutine ctx_getlun(this, unit)
      class(pepper_context), intent(inout) :: this  !! the context
      integer(ip), intent(out) :: unit  !! the unit
      if (this%return()) return
      call this%fndlun(unit)
      if (unit == 0) then
         call this%setmsg('No free logical units are available.')
         call this%sigerr('SPICE(NOFREELOGICALUNIT)')
      else if (unit < 0) then
         call this%setmsg('INQUIRE iostat was #.')
         call this%errint('#', -unit)
         call this%sigerr('SPICE(INQUIREFAILED)')
         unit = 0
      end if
   end subroutine ctx_getlun

   !> Reserve a logical unit: fndlun and getlun do not give it (SPICELIB's
   !> RESLUN). Units outside 1:99 are ignored.
   subroutine ctx_reslun(this, unit)
      class(pepper_context), intent(inout) :: this  !! the context
      integer(ip), intent(in) :: unit  !! the unit
      if (unit >= 1 .and. unit <= 99) this%spice%reserved_units(unit) = .true.
   end subroutine ctx_reslun

   !> Free a reserved logical unit (SPICELIB's FRELUN).
   subroutine ctx_frelun(this, unit)
      class(pepper_context), intent(inout) :: this  !! the context
      integer(ip), intent(in) :: unit  !! the unit
      if (unit >= 1 .and. unit <= 99) this%spice%reserved_units(unit) = .false.
   end subroutine ctx_frelun

   ! ------------------------------------------------------------------------
   ! The hash with a divisor set once (SPICELIB's ZZSHSH, ZZHASH, ZZHASH2):
   ! the values of name_hash. The divisor belongs to the instance.

   !> Set the divisor of zzhash; returns 0 (SPICELIB's ZZSHSH).
   integer(ip) function ctx_zzshsh(this, m)
      class(pepper_context), intent(inout) :: this  !! the context
      integer(ip), intent(in) :: m  !! the divisor (number of hash values)
      integer(ip), parameter :: maxdiv = huge(1_ip) / 68 - 1
      ctx_zzshsh = 0
      if (m <= 0 .or. m > maxdiv) then
         call this%setmsg('The input hash function divisor was not in the allowed range from 1 to #. It was #.')
         call this%errint('#', maxdiv)
         call this%errint('#', m)
         call this%sigerr('SPICE(INVALIDDIVISOR)')
         return
      end if
      this%spice%hash_divisor = m
   end function ctx_zzshsh

   !> The hash value of a word, from 1 to the divisor set with zzshsh
   !> (SPICELIB's ZZHASH).
   integer(ip) function ctx_zzhash(this, word)
      class(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: word  !! the word (it ends at its first blank)
      if (this%spice%hash_divisor == -1) then
         ctx_zzhash = 0
         call this%setmsg('The ZZHASH function was called before the POOL hash parameters were '// &
                          'initialized by a call to ZZSHSH.')
         call this%sigerr('SPICE(CALLEDOUTOFORDER)')
         return
      end if
      ctx_zzhash = name_hash(word, this%spice%hash_divisor)
   end function ctx_zzhash

   !> The hash value of a word, from 1 to m2 (SPICELIB's ZZHASH2).
   integer(ip) function ctx_zzhash2(this, word, m2)
      class(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: word  !! the word (it ends at its first blank)
      integer(ip), intent(in) :: m2  !! the divisor
      integer(ip), parameter :: maxdiv = huge(1_ip) / 68 - 1
      if (m2 <= 0 .or. m2 > maxdiv) then
         ctx_zzhash2 = 0
         call this%setmsg('The input hash function divisor was not in the allowed range from 1 to #. It was #.')
         call this%errint('#', maxdiv)
         call this%errint('#', m2)
         call this%sigerr('SPICE(INVALIDDIVISOR)')
         return
      end if
      ctx_zzhash2 = name_hash(word, m2)
   end function ctx_zzhash2

   ! ------------------------------------------------------------------------
   ! Helpers

   !> Replace the first occurrence of marker (without its leading and
   !> trailing blanks) in the long message with string, if the long message
   !> may be changed (see sigerr).
   subroutine replace_marker(this, marker, string)
      type(pepper_context), intent(inout) :: this  !! the context
      character(*), intent(in) :: marker  !! marker, e.g. '#'
      character(*), intent(in) :: string  !! replacement text (used as is)
      character(:), allocatable :: mark
      integer :: k
      if (.not. this%messages_allowed) return
      if (.not. allocated(this%long)) return
      mark = trim(adjustl(marker))
      if (len(mark) == 0) return
      k = index(this%long, mark)
      if (k == 0) return
      this%long = this%long(:k - 1) // string // this%long(k + len(mark):)
   end subroutine replace_marker

   !> The length of a string that may not be allocated (0 if it is not).
   !>
   !> PEPPER: the functions of this module that return strings give them
   !> the length of a specification expression like this one, not a
   !> deferred length (`character(:), allocatable` results): gfortran (at
   !> least up to 16.2) keeps the length of a deferred-length function
   !> result in a static variable at each call site (`slen`), which threads
   !> share, so concurrent calls get each other's lengths and corrupt the
   !> heap. Functions with a deferred-length result are not used.
   pure integer function text_length(s) result(n)
      character(:), allocatable, intent(in) :: s  !! the string
      n = 0
      if (allocated(s)) n = len(s)
   end function text_length

   !> The short error message (blank if none).
   pure function short_text(this) result(msg)
      type(pepper_context), intent(in) :: this  !! the context
      character(text_length(this%short)) :: msg  !! the message
      if (allocated(this%short)) then
         msg = this%short
      else
         msg = ''
      end if
   end function short_text

   !> The long error message (blank if none).
   pure function long_text(this) result(msg)
      type(pepper_context), intent(in) :: this  !! the context
      character(text_length(this%long)) :: msg  !! the message
      if (allocated(this%long)) then
         msg = this%long
      else
         msg = ''
      end if
   end function long_text

   !> The device of the error reports ('NULL' if never set).
   pure function device_text(this) result(device)
      type(pepper_context), intent(in) :: this  !! the context
      character(merge(text_length(this%device), 4, allocated(this%device))) :: device  !! the device
      if (allocated(this%device)) then
         device = this%device
      else
         device = 'NULL'
      end if
   end function device_text

   !> Uppercase version of a string (ASCII letters).
   pure function upper(s) result(u)
      character(*), intent(in) :: s  !! the string
      character(len(s)) :: u
      integer :: i
      u = s
      do i = 1, len(s)
         if (u(i:i) >= 'a' .and. u(i:i) <= 'z') u(i:i) = achar(iachar(u(i:i)) - 32)
      end do
   end function upper

end module pepper_instance_module
